<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { faultApi, type RepairMaterial, type RepairOrder } from '@/api/fault'
import { systemApi, type UserRow } from '@/api/system'
import { useAuthStore } from '@/stores/auth'
import { errorMessage } from '@/utils/http'

const route = useRoute(); const auth = useAuthStore(); const loading = ref(false); const rows = ref<RepairOrder[]>([]); const total = ref(0); const users = ref<UserRow[]>([])
const query = reactive({ keyword: '', status: undefined as string | undefined, mineOnly: route.path.includes('my-repairs'), page: 1, pageSize: 100 })
const assignVisible = ref(false); const completeVisible = ref(false); const materialVisible = ref(false); const selected = ref<RepairOrder>(); const materials = ref<RepairMaterial[]>([])
const assignment = reactive({ primaryRepairerUserId: undefined as number | undefined, collaboratorUserIds: [] as number[] })
const completion = reactive({ repairMeasure: '', repairConclusion: '' }); const material = reactive({ materialCode: '', materialName: '', quantity: 1, unit: '件', unitPrice: 0, remark: '' })
const statuses: Record<string,string> = { PENDING_ASSIGNMENT:'待派工', ASSIGNED:'待维修', IN_PROGRESS:'维修中', PAUSED:'已挂起', PENDING_ACCEPTANCE:'待验收', CLOSED:'已关闭', CANCELLED:'已取消' }
onMounted(async()=>{ await Promise.all([load(), loadUsers()]) })
async function load(){ loading.value=true; try{const result=await faultApi.repairs(query);rows.value=result.records;total.value=result.total}catch(error){ElMessage.error(errorMessage(error,'维修工单加载失败'))}finally{loading.value=false} }
async function loadUsers(){try{users.value=(await systemApi.users({page:1,pageSize:100})).records}catch{users.value=[]}}
function openAssign(row:RepairOrder){selected.value=row;assignment.primaryRepairerUserId=row.primaryRepairerUserId;assignment.collaboratorUserIds=[...row.collaboratorUserIds];assignVisible.value=true}
async function saveAssign(){if(!selected.value||!assignment.primaryRepairerUserId)return ElMessage.warning('请选择主维修人');try{await faultApi.assign(selected.value.id,{...assignment,version:selected.value.version});assignVisible.value=false;await load();ElMessage.success('派工完成')}catch(error){ElMessage.error(errorMessage(error))}}
async function action(row:RepairOrder,type:'start'|'pause'|'resume'){try{await faultApi[type](row.id,{remark:'',version:row.version});await load()}catch(error){ElMessage.error(errorMessage(error))}}
function openComplete(row:RepairOrder){selected.value=row;completion.repairMeasure='';completion.repairConclusion='';completeVisible.value=true}
async function saveComplete(){if(!selected.value||!completion.repairMeasure||!completion.repairConclusion)return ElMessage.warning('请填写维修措施和结论');try{await faultApi.complete(selected.value.id,{...completion,attachmentIds:[],version:selected.value.version});completeVisible.value=false;await load();ElMessage.success('已提交验收')}catch(error){ElMessage.error(errorMessage(error))}}
async function acceptance(row:RepairOrder,passed:boolean){try{const{value}=await ElMessageBox.prompt(passed?'请输入验收意见':'请输入驳回原因',passed?'验收通过':'验收驳回',{inputValidator:value=>Boolean(value?.trim())||'请输入意见'});await faultApi.acceptance(row.id,{passed,comment:value,restoreStatusCode:row.restoreStatusCode||'IDLE',attachmentIds:[],version:row.version});await load()}catch(error){if(error!=='cancel'&&error!=='close')ElMessage.error(errorMessage(error))}}
async function openMaterial(row:RepairOrder){selected.value=row;materials.value=await faultApi.materials(row.id);materialVisible.value=true}
async function addMaterial(){if(!selected.value||!material.materialName)return;try{await faultApi.addMaterial(selected.value.id,{...material});materials.value=await faultApi.materials(selected.value.id);Object.assign(material,{materialCode:'',materialName:'',quantity:1,unit:'件',unitPrice:0,remark:''})}catch(error){ElMessage.error(errorMessage(error))}}
const pageTitle=computed(()=>query.mineOnly?'我的维修':'维修工单');const money=(value:number)=>Number(value||0).toFixed(2)
</script>

<template><div class="page-shell"><header class="page-header"><div><h1>{{pageTitle}}</h1><p>派工、执行、暂停、完工、验收和材料费用形成完整维修履历。</p></div></header><section class="surface-card query-bar"><el-input v-model="query.keyword" clearable placeholder="工单、报修单、设备或故障" style="width:300px"/><el-select v-model="query.status" clearable placeholder="状态" style="width:160px"><el-option v-for="(label,value) in statuses" :key="value" :label="label" :value="value"/></el-select><el-button type="primary" plain @click="query.page=1;load()">查询</el-button></section><section class="surface-card table-card"><el-table v-loading="loading" :data="rows" row-key="id"><el-table-column prop="repairCode" label="维修工单" width="170"/><el-table-column label="设备/故障" min-width="260"><template #default="{row}"><b>{{row.equipmentCode}} · {{row.equipmentName}}</b><small class="block">{{row.faultTitle}}</small></template></el-table-column><el-table-column prop="primaryRepairerName" label="主维修人" width="130"/><el-table-column label="工时" width="100"><template #default="{row}">{{Math.round(row.effectiveWorkSeconds/60)}} 分</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag>{{statuses[row.repairStatus]||row.repairStatus}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="360" fixed="right"><template #default="{row}"><el-button v-if="['PENDING_ASSIGNMENT','ASSIGNED'].includes(row.repairStatus)&&auth.can('fault:repair:assign')" link type="primary" @click="openAssign(row)">派工</el-button><el-button v-if="row.repairStatus==='ASSIGNED'&&auth.can('fault:repair:execute')" link @click="action(row,'start')">开始</el-button><el-button v-if="row.repairStatus==='IN_PROGRESS'&&auth.can('fault:repair:execute')" link type="warning" @click="action(row,'pause')">暂停</el-button><el-button v-if="row.repairStatus==='PAUSED'&&auth.can('fault:repair:execute')" link @click="action(row,'resume')">恢复</el-button><el-button v-if="row.repairStatus==='IN_PROGRESS'&&auth.can('fault:repair:execute')" link type="success" @click="openComplete(row)">完工</el-button><el-button v-if="row.repairStatus==='PENDING_ACCEPTANCE'&&auth.can('fault:repair:accept')" link type="success" @click="acceptance(row,true)">验收</el-button><el-button v-if="row.repairStatus==='PENDING_ACCEPTANCE'&&auth.can('fault:repair:accept')" link type="danger" @click="acceptance(row,false)">驳回</el-button><el-button v-if="auth.can('fault:material:manage')" link @click="openMaterial(row)">材料</el-button></template></el-table-column></el-table><div class="table-pagination"><el-pagination v-model:current-page="query.page" v-model:page-size="query.pageSize" :total="total" layout="total, sizes, prev, pager, next" @change="load"/></div></section>
<el-dialog v-model="assignVisible" title="维修派工" width="min(620px,95vw)"><el-form label-position="top"><el-form-item label="主维修人"><el-select v-model="assignment.primaryRepairerUserId" filterable style="width:100%"><el-option v-for="user in users" :key="user.id" :label="`${user.realName}（${user.username}）`" :value="user.id"/></el-select></el-form-item><el-form-item label="协作人"><el-select v-model="assignment.collaboratorUserIds" multiple filterable style="width:100%"><el-option v-for="user in users.filter(item=>item.id!==assignment.primaryRepairerUserId)" :key="user.id" :label="`${user.realName}（${user.username}）`" :value="user.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="assignVisible=false">取消</el-button><el-button type="primary" @click="saveAssign">确认派工</el-button></template></el-dialog>
<el-dialog v-model="completeVisible" title="维修完工" width="min(620px,95vw)"><el-form label-position="top"><el-form-item label="维修措施"><el-input v-model="completion.repairMeasure" type="textarea" :rows="4"/></el-form-item><el-form-item label="维修结论"><el-input v-model="completion.repairConclusion" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="completeVisible=false">取消</el-button><el-button type="primary" @click="saveComplete">提交验收</el-button></template></el-dialog>
<el-dialog v-model="materialVisible" title="维修材料" width="min(820px,96vw)"><el-table :data="materials" size="small"><el-table-column prop="materialName" label="名称"/><el-table-column prop="quantity" label="数量"/><el-table-column prop="unit" label="单位"/><el-table-column label="金额"><template #default="{row}">¥{{money(row.totalAmount)}}</template></el-table-column></el-table><el-form :model="material" inline class="material-form"><el-form-item><el-input v-model="material.materialName" placeholder="材料名称"/></el-form-item><el-form-item><el-input-number v-model="material.quantity" :min="0.0001"/></el-form-item><el-form-item><el-input v-model="material.unit" placeholder="单位"/></el-form-item><el-form-item><el-input-number v-model="material.unitPrice" :min="0" :precision="2"/></el-form-item><el-button type="primary" @click="addMaterial">添加</el-button></el-form></el-dialog></div></template>

<style scoped>.block{display:block;color:var(--tpm-text-secondary);margin-top:3px}.material-form{margin-top:18px;display:flex;gap:8px;flex-wrap:wrap}</style>
